from forth import evaluate, StackUnderflowError

assert evaluate(["1 2 3 4 over + - *"]) == [1, -8]

assert evaluate([": foo 9 ;", "foo"]) == [9]
try:
    evaluate(["foo"])
except ValueError as exc:
    assert exc.args[0] == "undefined operation"
else:
    raise AssertionError("definitions leaked between evaluations")

try:
    evaluate([": bad dup dup ;", "1 bad"])
except StackUnderflowError as exc:
    assert type(exc) is StackUnderflowError
    assert exc.args[0] == "Insufficient number of items in stack"
    assert exc.message == exc.args[0]
else:
    raise AssertionError("expected StackUnderflowError")

try:
    evaluate(["7 0 /"])
except ZeroDivisionError as exc:
    assert exc.args[0] == "divide by zero"
else:
    raise AssertionError("expected ZeroDivisionError")

assert evaluate(": 1 2 3 +" ) if False else True
for bad in ([": 1 2 ;"], [": -1 2 ;"], [": ;"], ["1 ;"]):
    try:
        evaluate(bad)
    except ValueError as exc:
        assert exc.args[0] == "illegal operation", (bad, exc.args)
    else:
        raise AssertionError(("expected ValueError", bad))

assert evaluate([]) == []
assert evaluate([""]) == []
assert evaluate("1 2 +") == [3]
print("all corrected edge checks passed")
